update_rule.pseudocode:
if t == 0:
  if social_network_type == 'small_world':
    G = watts_strogatz_graph(n=population_size, k=average_degree, p=rewiring_prob, seed=random_seed)
  elif social_network_type == 'scale_free':
    G = barabasi_albert_graph(n=population_size, m=max(1,int(average_degree/2)), seed=random_seed)
  else:
    G = erdos_renyi_graph(n=population_size, p=average_degree/(population_size-1), seed=random_seed)
  for each edge (i,j) in G:
    assign tie_weight[i,j] ~ LogNormal(mean=log(peer_tie_weight_mean), sigma=0.25)
  for each person i:
    Person[i].peer_network_neighbors = neighbors of i in G
  output G and tie weights

if t == 0:
  assign persons to households via Poisson size sampling
  initialize Household.shared_mask_inventory and norm index
for each household H each day:
  # Share masks if member inventory below threshold
  for member m in H:
    if Person[m].mask_inventory < minimum_inventory_to_wear and Household[H].shared_mask_inventory > 0:
      transfer = min(share_rate * Household[H].shared_mask_inventory, minimum_inventory_to_wear - Person[m].mask_inventory)
      Household[H].shared_mask_inventory -= transfer
      Person[m].mask_inventory += transfer
  # Normative reinforcement
  adoption_fraction = mean(Person[m].current_adoption_state for m in H)
  for member m in H:
    norm_signal = within_household_influence_weight * (adoption_fraction - 0.5)
    Person[m].susceptibility_to_influence = clip(Person[m].susceptibility_to_influence + 0.1*norm_signal, 0, 1)

if t == policy_mandate_start_day and PolicyMaker.mandate_status == false:
  PolicyMaker.mandate_status = true
  for each location L:
    if random() < mask_policy_in_locations_fraction:
      L.mask_policy = true
    L.enforcement_level = enforcement_probability
# Update enforcement intensity globally
PolicyMaker.enforcement_intensity = enforcement_probability
# Subsidies are applied directly to retailer prices downstream

visits = []
for each person i:
  n_visits ~ Poisson( mobility_effect_on_visits * EpidemiologicalContext.mobility_level )
  for k in 1..n_visits:
    select location L with probability proportional to L.foot_traffic_rate
    visits.append( (i, L) )
# Observe compliance and send to Enforcement
for each location L:
  V = [i for (i,L2) in visits if L2==L]
  if len(V) > 0:
    comp = mean(Person[i].current_adoption_state for i in V)
  else:
    comp = 0
  L.current_observed_compliance = comp
# Enforcement events delegated
emit EnforcementModule.enforcement_events = visits
